using ecom.Models;

class Program
{
    static void Main()
    {
        IEnumerable<User> users = new List<User>
        {
            new User { Id = 1, Name = "Ali", Email = "ali@mail.com", Password = "123", IsActive = true },
            new User { Id = 2, Name = "Veli", Email = "veli@mail.com", Password = "456", IsActive = false },
            new User { Id = 3, Name = "Aysel", Email = "aysel@mail.com", Password = "789", IsActive = true },
            new User { Id = 4, Name = "Kamran", Email = "ali@mail.com", Password = "000", IsActive = true }
        };

        var activeUsers = users.Where(u => u.IsActive);

        foreach (var user in activeUsers)
        {
            Console.WriteLine($"{user.Name} - {user.Email}");
        }
    }                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
